<script setup>
import { computed, ref } from 'vue';
import { decodeSellerPageData } from '../utils/sellerPageData';
const props = defineProps({ pageData: { type: String, default: '' } });
const data = decodeSellerPageData(props.pageData);
const search = ref(data.search || '');
const hasSearch = computed(() => Boolean(search.value));
</script>

<template>
    <div class="seller-sales-page">
        <div class="seller-page-heading"><div><h1>Sales</h1><p>Track your completed sales and revenue.</p></div></div>
        <div class="seller-sales-stats"><div class="seller-sales-stat-card"><div class="seller-sales-stat-icon sales"><i class="bi bi-receipt"></i></div><div class="seller-sales-stat-content"><span>Total Sales</span><h3>{{ data.totalSales }}</h3></div></div><div class="seller-sales-stat-card"><div class="seller-sales-stat-icon items"><i class="bi bi-box-seam"></i></div><div class="seller-sales-stat-content"><span>Items Sold</span><h3>{{ data.totalItemsSold }}</h3></div></div><div class="seller-sales-stat-card"><div class="seller-sales-stat-icon revenue"><i class="bi bi-currency-dollar"></i></div><div class="seller-sales-stat-content"><span>Total Revenue</span><h3>${{ data.totalRevenue }}</h3></div></div><div class="seller-sales-stat-card"><div class="seller-sales-stat-icon average"><i class="bi bi-graph-up-arrow"></i></div><div class="seller-sales-stat-content"><span>Average Sale</span><h3>${{ data.averageSale }}</h3></div></div></div>
        <div class="seller-sales-panel"><div class="seller-sales-panel-header"><div class="seller-sales-panel-title"><div class="seller-sales-panel-icon"><i class="bi bi-graph-up"></i></div><div><h5>Sales History</h5><p>View your completed orders and earnings.</p></div></div><div class="seller-sales-count"><i class="bi bi-receipt"></i>{{ data.pagination.total }} {{ data.pagination.total === 1 ? 'sale' : 'sales' }}</div></div>
            <div class="seller-sales-filter"><form :action="data.indexUrl" method="GET"><div class="seller-sales-search"><div class="seller-sales-search-input"><i class="bi bi-search"></i><input v-model="search" type="text" name="search" placeholder="Search sales..."></div><button type="submit" class="seller-sales-search-button"><i class="bi bi-search"></i><span>Search</span></button><a v-if="hasSearch" :href="data.indexUrl" class="seller-sales-reset-button"><i class="bi bi-arrow-counterclockwise"></i><span>Reset</span></a></div></form></div>
            <div v-if="data.sales.length" class="table-responsive"><table class="seller-sales-table"><thead><tr><th>Order</th><th>Book</th><th>Buyer</th><th>Quantity</th><th>Price</th><th>Total</th><th>Date</th></tr></thead><tbody><tr v-for="sale in data.sales" :key="sale.id"><td><div class="seller-sale-order"><strong>#{{ sale.orderNumber }}</strong><span><i></i>Delivered</span></div></td><td><div class="seller-sale-book"><div class="seller-sale-book-cover"><img v-if="sale.coverUrl" :src="sale.coverUrl" :alt="sale.bookTitle"><i v-else class="bi bi-book"></i></div><div class="seller-sale-book-info"><strong>{{ sale.bookTitle }}</strong><span v-if="sale.author">{{ sale.author }}</span></div></div></td><td><div class="seller-sale-buyer"><div class="seller-sale-buyer-avatar">{{ sale.buyerInitial }}</div><div><strong>{{ sale.buyerName }}</strong><span>{{ sale.buyerEmail }}</span></div></div></td><td><span class="seller-sale-quantity">{{ sale.quantity }}</span></td><td><span class="seller-sale-price">${{ sale.bookPrice }}</span></td><td><strong class="seller-sale-total">${{ sale.totalPrice }}</strong></td><td><div class="seller-sale-date"><strong>{{ sale.date }}</strong><span>{{ sale.time }}</span></div></td></tr></tbody></table></div>
            <div v-if="data.pagination.links.length > 3" class="seller-sales-pagination"><nav aria-label="Pagination"><a v-for="(link, index) in data.pagination.links" :key="index" :href="link.url || undefined" :class="{ active: link.active, disabled: !link.url }" v-html="link.label"></a></nav></div>
            <div v-if="!data.sales.length" class="seller-sales-empty"><div class="seller-sales-empty-icon"><i class="bi bi-graph-up"></i></div><h5>No Sales Found</h5><p>You don't have any completed sales matching your search.</p><a v-if="hasSearch" :href="data.indexUrl" class="seller-sales-empty-button"><i class="bi bi-arrow-counterclockwise"></i><span>Clear Search</span></a></div>
        </div>
    </div>
</template>
